// Single-file copy of supabase/functions/halal-places/index.ts for deploying from the
// Supabase dashboard. Generated by supabase/build-dashboard-functions.mjs — do not edit.

import "jsr:@supabase/functions-js/edge-runtime.d.ts";

/**
 * Halal Places — OpenStreetMap lookup.
 *
 *   GET ?lat=..&lng=..&radius=5000   halal shops, restaurants and mosques nearby
 *   GET ?q=Ottawa                    city / place search (for the location picker)
 *   GET ?address=123 Bank St Ottawa  address geocoding (for "Add a place")
 *
 * Data comes from the public Overpass and Nominatim APIs. Results are cached
 * in memory for a short time so repeated searches don't hammer them.
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey, X-Sync-Token",
};

const USER_AGENT = "Firdam/1.0 (https://firdam.com)";

const OVERPASS_ENDPOINTS = [
  "https://overpass-api.de/api/interpreter",
  "https://maps.mail.ru/osm/tools/overpass/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
  "https://overpass.private.coffee/api/interpreter",
];

type Category = "grocery" | "butcher" | "restaurant" | "cafe" | "mosque" | "other";

interface OsmElement {
  type: "node" | "way" | "relation";
  id: number;
  lat?: number;
  lon?: number;
  center?: { lat: number; lon: number };
  tags?: Record<string, string>;
}

interface NormalizedPlace {
  key: string;
  source: "osm";
  name: string;
  category: Category;
  latitude: number;
  longitude: number;
  address: string | null;
  phone: string | null;
  website: string | null;
  openingHours: string | null;
  /** may_sell: a food shop not marked halal on the map that often stocks halal food. */
  halalStatus: "halal" | "halal_only" | "halal_options" | "mosque" | "may_sell";
  certification: string | null;
  cuisine: string | null;
}

const CACHE_TTL_MS = 30 * 60 * 1000;
const cache = new Map<string, { at: number; body: unknown }>();

function cached<T>(key: string): T | null {
  const hit = cache.get(key);
  if (!hit) return null;
  if (Date.now() - hit.at > CACHE_TTL_MS) {
    cache.delete(key);
    return null;
  }
  return hit.body as T;
}

function remember(key: string, body: unknown) {
  if (cache.size > 500) {
    const oldest = cache.keys().next().value;
    if (oldest) cache.delete(oldest);
  }
  cache.set(key, { at: Date.now(), body });
}

// ---- Our own store of places (osm_places), filled per 0.2° map tile ----
const TILE = 0.2;
const REFRESH_MS = 14 * 24 * 3600_000;

interface Tile { tile: string; south: number; west: number; north: number; east: number }

function tilesFor(lat: number, lng: number, radius: number): { tiles: Tile[]; box: [number, number, number, number] } {
  const dLat = radius / 111_320;
  const dLng = radius / (111_320 * Math.max(0.2, Math.cos((lat * Math.PI) / 180)));
  const box: [number, number, number, number] = [lat - dLat, lng - dLng, lat + dLat, lng + dLng];
  const tiles: Tile[] = [];
  for (let y = Math.floor(box[0] / TILE); y <= Math.floor(box[2] / TILE); y++) {
    for (let x = Math.floor(box[1] / TILE); x <= Math.floor(box[3] / TILE); x++) {
      tiles.push({ tile: `${y}:${x}`, south: +(y * TILE).toFixed(4), west: +(x * TILE).toFixed(4), north: +((y + 1) * TILE).toFixed(4), east: +((x + 1) * TILE).toFixed(4) });
    }
  }
  return { tiles, box };
}

function tileQuery(t: Tile): string {
  return `
    [out:json][timeout:60][bbox:${t.south},${t.west},${t.north},${t.east}];
    (
      nwr["diet:halal"~"^(yes|only|limited)$"];
      nwr["halal"="yes"];
      nwr["cuisine"~"halal",i];
      nwr["amenity"="place_of_worship"]["religion"="muslim"];
      nwr["shop"]["name"~"halal",i];
      nwr["amenity"~"^(restaurant|fast_food|cafe)$"]["name"~"halal",i];
    )->.halal;
    .halal out center tags;
    (nwr["shop"~"^(supermarket|grocery|butcher|deli|spices|food|greengrocer)$"]; - .halal;)->.stores;
    .stores out center tags 600;
  `;
}

async function rest<T>(path: string, init: RequestInit = {}): Promise<T | null> {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) return null;
  const res = await fetch(`${url}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json", ...(init.headers ?? {}) },
  });
  if (!res.ok) {
    console.error(`rest ${path.split("?")[0]} ${res.status}: ${(await res.text()).slice(0, 300)}`);
    return null;
  }
  const text = await res.text();
  return (text ? JSON.parse(text) : null) as T;
}

/** Stores one tile's places (replacing what was there) and marks it fetched. */
async function ingestTile(t: Tile, elements: OsmElement[]): Promise<number> {
  const started = new Date().toISOString();
  const seen = new Set<string>();
  const rows = [];
  for (const el of elements) {
    const p = normalize(el);
    if (!p || seen.has(p.key)) continue;
    seen.add(p.key);
    rows.push({
      key: p.key, tile: t.tile, name: p.name, category: p.category, latitude: p.latitude, longitude: p.longitude,
      address: p.address, phone: p.phone, website: p.website, opening_hours: p.openingHours,
      halal_status: p.halalStatus, certification: p.certification, cuisine: p.cuisine, updated_at: started,
    });
  }
  for (let i = 0; i < rows.length; i += 500) {
    await rest("osm_places?on_conflict=key", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify(rows.slice(i, i + 500)),
    });
  }
  await rest(`osm_places?tile=eq.${encodeURIComponent(t.tile)}&updated_at=lt.${encodeURIComponent(started)}`, { method: "DELETE" });
  await rest("place_areas?on_conflict=tile", {
    method: "POST",
    headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify({ ...t, fetched_at: new Date().toISOString(), attempts: 0 }),
  });
  return rows.length;
}

interface PlaceRow {
  key: string; name: string; category: Category; latitude: number; longitude: number; address: string | null;
  phone: string | null; website: string | null; opening_hours: string | null; halal_status: NormalizedPlace["halalStatus"];
  certification: string | null; cuisine: string | null;
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

const GROCERY_SHOPS = new Set([
  "supermarket",
  "convenience",
  "grocery",
  "greengrocer",
  "deli",
  "general",
  "food",
  "frozen_food",
  "spices",
  "health_food",
]);

function categorize(tags: Record<string, string>): Category {
  if (tags.amenity === "place_of_worship") return "mosque";
  if (tags.shop === "butcher") return "butcher";
  if (tags.shop && GROCERY_SHOPS.has(tags.shop)) return "grocery";
  if (["restaurant", "fast_food", "food_court"].includes(tags.amenity ?? "")) return "restaurant";
  if (tags.amenity === "cafe" || ["bakery", "pastry", "confectionery"].includes(tags.shop ?? "")) {
    return "cafe";
  }
  return "other";
}

function buildAddress(tags: Record<string, string>): string | null {
  if (tags["addr:full"]) return tags["addr:full"];
  const street = [tags["addr:housenumber"], tags["addr:street"]].filter(Boolean).join(" ");
  const parts = [street, tags["addr:city"] ?? tags["addr:suburb"], tags["addr:postcode"]].filter(
    Boolean,
  );
  return parts.length ? parts.join(", ") : null;
}

function normalize(el: OsmElement): NormalizedPlace | null {
  const tags = el.tags ?? {};
  const lat = el.lat ?? el.center?.lat;
  const lon = el.lon ?? el.center?.lon;
  if (lat === undefined || lon === undefined) return null;

  const category = categorize(tags);
  const name = tags.name ?? tags["name:en"] ?? tags.brand ?? null;
  if (!name) return null;

  const dietHalal = (tags["diet:halal"] ?? tags.halal ?? "").toLowerCase();
  let halalStatus: NormalizedPlace["halalStatus"];
  if (category === "mosque") halalStatus = "mosque";
  else if (dietHalal === "only") halalStatus = "halal_only";
  else if (dietHalal === "limited") halalStatus = "halal_options";
  else if (
    !["yes", "only"].includes(dietHalal) &&
    !/halal/i.test(`${tags.cuisine ?? ""} ${name}`) &&
    (category === "grocery" || category === "butcher")
  ) halalStatus = "may_sell";
  else halalStatus = "halal";

  return {
    key: `osm:${el.type}/${el.id}`,
    source: "osm",
    name,
    category,
    latitude: lat,
    longitude: lon,
    address: buildAddress(tags),
    phone: tags.phone ?? tags["contact:phone"] ?? null,
    website: tags.website ?? tags["contact:website"] ?? null,
    openingHours: tags.opening_hours ?? null,
    halalStatus,
    certification: tags["diet:halal:certification"] ?? tags["halal:certification"] ?? null,
    cuisine: tags.cuisine ? tags.cuisine.replace(/;/g, ", ").replace(/_/g, " ") : null,
  };
}

function travelQuery(lat: number, lng: number, radius: number): string {
  return `
    [out:json][timeout:30];
    (
      nwr(around:${radius},${lat},${lng})["shop"="travel_agency"];
      nwr(around:${radius},${lat},${lng})["office"="travel_agent"];
    );
    out center tags 200;
  `;
}

interface TravelAgency {
  key: string;
  name: string;
  latitude: number;
  longitude: number;
  address: string | null;
  phone: string | null;
  website: string | null;
  openingHours: string | null;
  /** Name mentions Hajj, Umrah, Islamic, halal or similar. */
  muslimFocused: boolean;
}

const MUSLIM_TRAVEL_RE = /(hajj|umrah|umra|halal|islam|muslim|makkah|mecca|madinah|medina|haram|zamzam|hijaz)/i;

function normalizeAgency(el: OsmElement): TravelAgency | null {
  const tags = el.tags ?? {};
  const lat = el.lat ?? el.center?.lat;
  const lon = el.lon ?? el.center?.lon;
  const name = tags.name ?? tags.brand;
  if (lat === undefined || lon === undefined || !name) return null;
  return {
    key: `osm:${el.type}/${el.id}`,
    name,
    latitude: lat,
    longitude: lon,
    address: buildAddress(tags),
    phone: tags.phone ?? tags["contact:phone"] ?? null,
    website: tags.website ?? tags["contact:website"] ?? null,
    openingHours: tags.opening_hours ?? null,
    muslimFocused: MUSLIM_TRAVEL_RE.test(`${name} ${tags.description ?? ""}`),
  };
}

async function queryOverpass(lat: number, lng: number, radius: number, rawQuery?: string, stores = false, budgetMs = 55_000): Promise<OsmElement[]> {
  // A bounding box with tag filters is far lighter for the public servers than
  // collecting every shop and amenity in the area first.
  const dLat = radius / 111_320;
  const dLng = radius / (111_320 * Math.max(0.2, Math.cos((lat * Math.PI) / 180)));
  const bbox = [lat - dLat, lng - dLng, lat + dLat, lng + dLng].map((n) => n.toFixed(5)).join(",");
  const query = rawQuery ?? `
    [out:json][timeout:25][bbox:${bbox}];
    (
      nwr["diet:halal"~"^(yes|only|limited)$"];
      nwr["halal"="yes"];
      nwr["cuisine"~"halal",i];
      nwr["amenity"="place_of_worship"]["religion"="muslim"];
      nwr["shop"]["name"~"halal",i];
      nwr["amenity"~"^(restaurant|fast_food|cafe)$"]["name"~"halal",i];
    )->.halal;
    .halal out center tags 400;${stores ? `
    (nwr["shop"~"^(supermarket|grocery|butcher|deli|spices|food|greengrocer)$"]; - .halal;)->.stores;
    .stores out center tags 250;` : ""}
  `;

  // Hedged requests: ask the main server first, and if it hasn't answered after
  // a few seconds also ask the mirrors. The first good answer wins; the rest are
  // cancelled. This keeps searches fast when one public server is overloaded.
  const STAGGER_MS = budgetMs < 30_000 ? 3_000 : 6_000;
  const deadline = Date.now() + budgetMs;
  const controllers = OVERPASS_ENDPOINTS.map(() => new AbortController());
  const attempt = async (endpoint: string, i: number): Promise<OsmElement[]> => {
    if (i > 0) await new Promise((r) => setTimeout(r, i * STAGGER_MS));
    if (controllers[i].signal.aborted) throw new Error("cancelled");
    const timer = setTimeout(() => controllers[i].abort(), Math.max(1_000, deadline - Date.now()));
    try {
      const res = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded", "User-Agent": USER_AGENT },
        body: `data=${encodeURIComponent(query)}`,
        signal: controllers[i].signal,
      });
      if (!res.ok) throw new Error(`Overpass ${res.status} from ${new URL(endpoint).host}`);
      const data = (await res.json()) as { elements?: OsmElement[]; remark?: string };
      // Overpass reports server-side timeouts as a 200 with a "remark" and no elements.
      if (!data.elements?.length && data.remark && /timed out|runtime error/i.test(data.remark)) {
        throw new Error(`Overpass busy (${new URL(endpoint).host})`);
      }
      return data.elements ?? [];
    } finally {
      clearTimeout(timer);
    }
  };
  try {
    const elements = await Promise.any(OVERPASS_ENDPOINTS.map((e, i) => attempt(e, i)));
    return elements;
  } catch (err) {
    const errors = err instanceof AggregateError ? err.errors : [err];
    throw errors.find((e) => !(e instanceof Error && e.message === "cancelled")) ?? new Error("Overpass unavailable");
  } finally {
    controllers.forEach((c) => c.abort());
  }
}

interface GeoResult {
  id: number;
  name: string;
  latitude: number;
  longitude: number;
  country: string;
  admin1?: string;
}

async function searchCities(q: string) {
  const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=8&language=en&format=json`;
  const res = await fetch(url);
  if (!res.ok) throw new Error("City search failed");
  const data = (await res.json()) as { results?: GeoResult[] };
  return (data.results ?? []).map((r) => ({
    id: r.id,
    name: r.name,
    country: r.country,
    region: r.admin1 ?? "",
    latitude: r.latitude,
    longitude: r.longitude,
    label: `${r.name}${r.admin1 ? `, ${r.admin1}` : ""}, ${r.country}`,
  }));
}

interface NominatimSearchResult {
  place_id: number;
  lat: string;
  lon: string;
  display_name: string;
  address?: { city?: string; town?: string; village?: string; country?: string };
}

async function geocodeAddress(address: string) {
  const url = `https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=5&q=${encodeURIComponent(address)}`;
  const res = await fetch(url, { headers: { "User-Agent": USER_AGENT, "Accept-Language": "en" } });
  if (!res.ok) throw new Error("Address search failed");
  const data = (await res.json()) as NominatimSearchResult[];
  return data.map((r) => ({
    id: r.place_id,
    label: r.display_name,
    latitude: Number(r.lat),
    longitude: Number(r.lon),
    city: r.address?.city ?? r.address?.town ?? r.address?.village ?? null,
    country: r.address?.country ?? null,
  }));
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  try {
    const url = new URL(req.url);
    const q = url.searchParams.get("q")?.trim();
    const address = url.searchParams.get("address")?.trim();
    const lat = Number(url.searchParams.get("lat"));
    const lng = Number(url.searchParams.get("lng"));
    const radius = Math.min(Math.max(Number(url.searchParams.get("radius")) || 5000, 500), 30000);

    if (q) {
      if (q.length < 2) return json({ places: [] });
      const key = `q:${q.toLowerCase()}`;
      const hit = cached<unknown>(key);
      if (hit) return json(hit);
      const body = { places: await searchCities(q) };
      remember(key, body);
      return json(body);
    }

    if (address) {
      if (address.length < 4) return json({ results: [] });
      const key = `a:${address.toLowerCase()}`;
      const hit = cached<unknown>(key);
      if (hit) return json(hit);
      const body = { results: await geocodeAddress(address) };
      remember(key, body);
      return json(body);
    }

    const kind = url.searchParams.get("kind");
    if (kind === "travel" && Number.isFinite(lat) && Number.isFinite(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180) {
      const key = `t:${lat.toFixed(2)}:${lng.toFixed(2)}:${radius}`;
      const hit = cached<unknown>(key);
      if (hit) return json(hit);
      const elements = await queryOverpass(lat, lng, radius, travelQuery(lat, lng, radius));
      const seen = new Set<string>();
      const agencies: TravelAgency[] = [];
      for (const el of elements) {
        const a = normalizeAgency(el);
        if (!a || seen.has(a.key)) continue;
        seen.add(a.key);
        agencies.push(a);
      }
      const body = { agencies, attribution: "© OpenStreetMap contributors" };
      remember(key, body);
      return json(body);
    }

    // Background sync (GitHub job): list tiles to fetch, and store fetched ones.
    const sync = url.searchParams.get("sync");
    if (sync) {
      const token = Deno.env.get("PLACES_SYNC_TOKEN");
      if (!token || req.headers.get("x-sync-token") !== token) return json({ error: "Not allowed." }, 403);
      if (sync === "pending") {
        const stale = new Date(Date.now() - REFRESH_MS).toISOString();
        const recent = new Date(Date.now() - 60 * 24 * 3600_000).toISOString();
        const tiles = await rest<Tile[]>(
          `place_areas?select=tile,south,west,north,east&requested_at=gte.${encodeURIComponent(recent)}&or=(fetched_at.is.null,fetched_at.lt.${encodeURIComponent(stale)})&order=fetched_at.nullsfirst,requested_at.desc&limit=25`,
        );
        return json({ tiles: (tiles ?? []).map((t) => ({ ...t, query: tileQuery(t) })) });
      }
      if (sync === "ingest" && req.method === "POST") {
        const body = (await req.json().catch(() => ({}))) as { tile?: Tile; elements?: OsmElement[] };
        if (!body.tile?.tile || !Array.isArray(body.elements)) return json({ error: "Send tile and elements." }, 400);
        return json({ stored: await ingestTile(body.tile, body.elements) });
      }
      return json({ error: "Unknown sync action." }, 400);
    }

    if (Number.isFinite(lat) && Number.isFinite(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180) {
      // Places always come from our own store, so the app never waits on the
      // public map servers. New areas are queued for the background job and,
      // when possible, fetched right away too.
      const stores = url.searchParams.get("stores") === "1";
      const { tiles, box } = tilesFor(lat, lng, radius);
      const known = (await rest<{ tile: string; fetched_at: string | null }[]>(
        `place_areas?select=tile,fetched_at&tile=in.(${tiles.map((t) => `"${t.tile}"`).join(",")})`,
      )) ?? [];
      const fetched = new Map(known.map((k) => [k.tile, k.fetched_at]));
      const now = new Date().toISOString();
      await rest("place_areas?on_conflict=tile", {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify(tiles.map((t) => ({ ...t, requested_at: now }))),
      });
      const neverFetched = tiles.filter((t) => !fetched.get(t.tile));
      // Try the nearest new tile live (short budget); the background job does the rest.
      const centre = neverFetched.find((t) => lat >= t.south && lat < t.north && lng >= t.west && lng < t.east) ?? neverFetched[0];
      if (centre) {
        try {
          const els = await queryOverpass(lat, lng, radius, tileQuery(centre), false, 15_000);
          await ingestTile(centre, els);
          fetched.set(centre.tile, now);
        } catch (err) {
          console.error(`live fetch ${centre.tile}: ${err instanceof Error ? err.message : err}`);
        }
      }
      const rows = (await rest<PlaceRow[]>(
        `osm_places?select=*&latitude=gte.${box[0]}&latitude=lte.${box[2]}&longitude=gte.${box[1]}&longitude=lte.${box[3]}${stores ? "" : "&halal_status=neq.may_sell"}&limit=2000`,
      )) ?? [];
      const places: NormalizedPlace[] = rows.map((r) => ({
        key: r.key, source: "osm", name: r.name, category: r.category, latitude: r.latitude, longitude: r.longitude,
        address: r.address, phone: r.phone, website: r.website, openingHours: r.opening_hours,
        halalStatus: r.halal_status, certification: r.certification, cuisine: r.cuisine,
      }));
      const pending = tiles.some((t) => !fetched.get(t.tile));
      return json({ places, pending, attribution: "© OpenStreetMap contributors" });
    }

    return json({ error: "Provide lat+lng, q, or address." }, 400);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";
    return json({ error: message }, 502);
  }
});
